/**
 * The flexible format accepts one to six product references and queues an eight-frame campaign. The strict front/back format requires exactly two references and queues seven final images.
 *   Open-source AI model requests are routed to the authenticated Colab
 *   GPU worker. FLUX.2 Pro is available through separate fal.ai and
 *   Black Forest Labs server-side image-editing routes. CPU preview is
 *   explicitly a source-preserved product compositor, not AI generation.
 * @summary Queue a selectable luxury product campaign
 */
export const createShootBodyProductNameDefault = `Untitled product`;
export const createShootBodyCategoryDefault = `Luxury handbag`;
export const createShootBodyAtmosphereDefault = `Quiet, architectural luxury`;
export const createShootBodyBackgroundDefault = `Luxury white studio`;
export const createShootBodyOutputFormatDefault = `png`;
export const createShootBodyEngineDefault = `auto`;
export const createShootBodySpeedModeDefault = `fast`;
export const createShootBodyCampaignFormatDefault = `flexible-8`;
export const createShootBodyGenerationModeDefault = `product-only`;
export const createShootBodyReferencesMax = 6;



export const CreateShootBody = zod.object({
  "product_name": zod.string().default(createShootBodyProductNameDefault),
  "category": zod.string().default(createShootBodyCategoryDefault),
  "atmosphere": zod.string().default(createShootBodyAtmosphereDefault),
  "background": zod.string().default(createShootBodyBackgroundDefault),
  "output_format": zod.enum(['png', 'jpeg', 'webp']).default(createShootBodyOutputFormatDefault),
  "engine": zod.enum(['rudras', 'auto', 'colab', 'qwen', 'qwen-runpod', 'flux1-runpod', 'gemini-image', 'flux-schnell', 'fooocus', 'hidream', 'flux2', 'flux2-pro', 'bfl-flux2', 'flux2-klein', 'sdxl', 'cpu']).default(createShootBodyEngineDefault),
  "speed_mode": zod.enum(['fast', 'campaign']).default(createShootBodySpeedModeDefault),
  "campaign_format": zod.enum(['compact-6', 'flexible-8', 'front-back-7']).default(createShootBodyCampaignFormatDefault).describe('Compact six-image model lookbook, flexible eight-frame campaign, or strict two-reference seven-image campaign'),
  "generation_mode": zod.enum(['product-only', 'human-model']).default(createShootBodyGenerationModeDefault).describe('Product-only catalog generation or category-aware human-model generation'),
  "model_reference": zod.instanceof(File).optional().describe('Dedicated model master image. Required for human-model generation.'),
  "references": zod.array(zod.instanceof(File)).min(1).max(createShootBodyReferencesMax)
})

